package com.kozhedub.atlantic4145;

import android.content.Context;
import android.graphics.*;
import android.view.*;
import java.util.*;

public class NavalGameView extends View {
    private final Paint p=new Paint(3); private final Random rnd=new Random();
    private int mode=0, playerHp=100, enemyHp=100; private float aim=0.50f; private long flash=0; private String msg="";
    public NavalGameView(Context c){super(c);p.setTypeface(Typeface.create("sans",Typeface.NORMAL));setKeepScreenOn(true);}
    private void txt(Canvas c,String s,float x,float y,float size,int color){p.setTextSize(size);p.setColor(color);p.setStyle(Paint.Style.FILL);c.drawText(s,x,y,p);}
    private void rect(Canvas c,float l,float t,float r,float b,int color){p.setColor(color);p.setStyle(Paint.Style.FILL);c.drawRoundRect(l,t,r,b,10,10,p);}
    @Override protected void onDraw(Canvas c){super.onDraw(c); if(mode==0) menu(c); else battle(c); invalidate();}
    private void sea(Canvas c){int w=getWidth(),h=getHeight(); Paint grad=new Paint(); grad.setShader(new LinearGradient(0,0,0,h,Color.rgb(91,166,199),Color.rgb(5,31,47),Shader.TileMode.CLAMP));c.drawRect(0,0,w,h,grad);p.setColor(0x448FD5E5);p.setStrokeWidth(2);for(int i=0;i<34;i++){float y=h*.38f+i*17;float off=(System.currentTimeMillis()/25+i*31)%160;c.drawLine(-160+off,y,w,y,p);}}
    private void ship(Canvas c,float x,float y,float sc,boolean enemy){p.setColor(enemy?0xff4e5358:0xff737b80);Path hull=new Path();hull.moveTo(x-150*sc,y);hull.lineTo(x+160*sc,y);hull.lineTo(x+110*sc,y+35*sc);hull.lineTo(x-120*sc,y+35*sc);hull.close();c.drawPath(hull,p);p.setColor(0xff343a3e);c.drawRect(x-65*sc,y-45*sc,x+65*sc,y, p);c.drawRect(x-22*sc,y-82*sc,x+24*sc,y-45*sc,p);p.setStrokeWidth(5*sc);c.drawLine(x,y-82*sc,x,y-130*sc,p);for(int i=-1;i<=1;i++){float tx=x+i*52*sc;p.setColor(0xff252a2d);c.drawCircle(tx,y-18*sc,19*sc,p);c.drawRect(tx,y-22*sc,tx+55*sc,y-17*sc,p);}}
    private void menu(Canvas c){sea(c);int w=getWidth(),h=getHeight();ship(c,w*.67f,h*.48f,1.15f,false);txt(c,"СРАЖЕНИЯ В АТЛАНТИКЕ",w*.08f,h*.17f,54,0xffe9e2c2);txt(c,"1941 — 1945",w*.19f,h*.24f,30,0xffd34b3f);String[] a={"УЧЕБНЫЙ БОЙ","ОДИНОЧНОЕ СРАЖЕНИЕ","КАМПАНИЯ (СКОРО)","НАСТРОЙКИ"};for(int i=0;i<a.length;i++){float y=h*.42f+i*74;rect(c,w*.08f,y,w*.39f,y+58,0xbb18232b);txt(c,a[i],w*.105f,y+39,25,0xffe4d39a);}txt(c,"v0.1 • первый прототип",w*.79f,h*.94f,18,0xffd5d5d5);}
    private void battle(Canvas c){sea(c);int w=getWidth(),h=getHeight();ship(c,w*.72f,h*.39f,.75f,true);ship(c,w*.27f,h*.68f,1.0f,false);txt(c,"HMS KING GEORGE V",24,38,22,Color.WHITE);txt(c,"БРОНЯ: "+playerHp+"%",24,70,20,0xff9ee79e);txt(c,"BISMARCK",w-230,38,22,Color.WHITE);txt(c,"ЦЕЛОСТНОСТЬ: "+enemyHp+"%",w-250,70,20,0xffffa0a0);float ax=w*(.48f+aim*.28f),ay=h*.37f;p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(3);p.setColor(0xffffd36a);c.drawCircle(ax,ay,28,p);c.drawLine(ax-42,ay,ax+42,ay,p);c.drawLine(ax,ay-42,ax,ay+42,p);rect(c,20,h-82,210,h-20,0xcc17242d);txt(c,"◀  КУРС  ▶",45,h-42,23,Color.WHITE);rect(c,w-245,h-92,w-25,h-20,0xcc7b2c25);txt(c,"ОГОНЬ ГК",w-210,h-46,26,Color.WHITE);rect(c,w*.40f,h-74,w*.60f,h-25,0xcc17242d);txt(c,"ПРИЦЕЛ  −     +",w*.425f,h-42,21,Color.WHITE);if(System.currentTimeMillis()-flash<260){p.setColor(0xaaffd25e);c.drawCircle(w*.32f,h*.62f,45,p);}if(!msg.isEmpty())txt(c,msg,w*.40f,h*.18f,28,0xffffe4a0);if(enemyHp<=0){txt(c,"ПОБЕДА",w*.43f,h*.5f,58,0xffffe08a);txt(c,"Коснитесь экрана для возврата",w*.37f,h*.57f,20,Color.WHITE);}}
    @Override public boolean onTouchEvent(android.view.MotionEvent e){if(e.getAction()!=MotionEvent.ACTION_DOWN)return true;float x=e.getX(),y=e.getY();int w=getWidth(),h=getHeight();if(mode==0){if(x>w*.07f&&x<w*.42f&&y>h*.38f&&y<h*.58f){mode=1;msg="Дистанция 14 800 м";}}else{if(enemyHp<=0){mode=0;enemyHp=100;playerHp=100;msg="";return true;}if(y>h-130&&x>w-290){flash=System.currentTimeMillis();int hit=18+rnd.nextInt(19);boolean ok=rnd.nextFloat()<.72f;if(ok){enemyHp=Math.max(0,enemyHp-hit);msg="ПОПАДАНИЕ! Урон "+hit+"%";}else msg="ПЕРЕЛЁТ — корректируйте прицел";}else if(y>h-110&&x>w*.38f&&x<w*.62f){aim+=(x>w*.5f?.04f:-.04f);aim=Math.max(0,Math.min(1,aim));msg="Поправка прицела: "+Math.round((aim-.5f)*100);}}return true;}
}
